/**
 * Fetches the committed dataset in the browser.
 *
 * `servers.json` is generated by `pnpm run build:data`; the page prerenders
 * its rows from the same file, and this copy drives filtering and sorting.
 */
import type { Server } from "../lib/server.ts";

import { parseServers } from "../lib/parse-servers.ts";

export type ServersState =
  | { readonly kind: "error"; readonly message: string }
  | { readonly kind: "ready"; readonly servers: readonly Server[] };

export async function loadServers(url = "servers.json"): Promise<ServersState> {
  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    return { kind: "ready", servers: parseServers(await response.json()) };
  } catch (error) {
    return {
      kind: "error",
      message: Error.isError(error) ? error.message : String(error),
    };
  }
}
